import{_ as e,o as s,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"2. 安装 C 编译器（gcc、clang、tinycc）","description":"The Little Book of C 中文版 — 2. 安装 C 编译器（gcc、clang、tinycc）","frontmatter":{"title":"2. 安装 C 编译器（gcc、clang、tinycc）","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 2. 安装 C 编译器（gcc、clang、tinycc）","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":2,"sidebarWeight":2,"alternateZh":"/posts/c教程/zh-CN/01-入门/002-Installing a C Compiler (gcc, clang, tinycc)","alternateEn":"/posts/c教程/en-US/01-Getting Started/002-Installing a C Compiler (gcc, clang, tinycc)"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/002-Installing a C Compiler (gcc, clang, tinycc).md","filePath":"posts/c教程/zh-CN/01-入门/002-Installing a C Compiler (gcc, clang, tinycc).md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/01-入门/002-Installing a C Compiler (gcc, clang, tinycc).md"};function c(l,a,p,o,d,g){return s(),t("div",null,[...a[0]||(a[0]=[n(`<p>[English version](/posts/c教程/en-US/01-Getting Started/002-Installing a C Compiler (gcc, clang, tinycc))</p><p>在编写和运行 C 程序之前，您需要一个编译器。编译器是一种将人类可读的代码转换为 CPU 可以理解的机器指令的工具。在 C 语言中，这个过程是明确的，你可以看到它，控制它，并从中学习。</p><p>有许多可用的编译器，但最常见的是以下三种：</p><ul><li>GCC（GNU 编译器集合）**，Linux 和 macOS 上的标准编译器，以可靠性和广泛支持而闻名。</li><li>Clang，一种现代编译器，旨在提高速度、更清晰的诊断以及与 LLVM 等工具的集成。</li><li>TinyCC (tcc)，一款超轻量级编译器，非常适合学习和快速测试。</li></ul><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>您可以通过在终端中运行以下命令之一来检查是否已安装编译器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc --version</span></span>
<span class="line"><span>clang --version</span></span>
<span class="line"><span>tcc --version</span></span></code></pre></div><p>如果您看到版本号，则说明您已准备就绪。如果没有，您需要安装一个。</p><h4 id="在不同系统上安装" tabindex="-1">在不同系统上安装 <a class="header-anchor" href="#在不同系统上安装" aria-label="Permalink to &quot;在不同系统上安装&quot;">​</a></h4><p>Linux（Debian/Ubuntu）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install build-essential</span></span></code></pre></div><p>这会安装 GCC 以及其他有用的工具，例如<code>make</code>.</p><p>macOS（使用 Xcode 命令行工具）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xcode-select --install</span></span></code></pre></div><p>这将安装 Clang 和开发人员工具链。</p><p>Windows（通过 Mingw-w64）：</p><ol><li>转到Mingw-w64。 2.下载并安装。 3.添加编译器<code>bin</code>文件夹到您的系统路径。</li><li>打开<code>cmd</code>或 PowerShell 并运行<code>gcc --version</code>确认。</li></ol><p>或者，如果您更喜欢一体化环境，请安装 WSL（适用于 Linux 的 Windows 子系统）并使用上面的 Linux 命令。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>安装编译器是了解程序如何成为可执行文件的第一步。在 C 中，没有隐藏的构建系统或自动运行时，编写代码和运行代码之间发生的所有事情都是可见的。这种清晰性是 C 语言成为如此强大的学习工具的部分原因。</p><p>当您安装编译器时，您还安装了探索软件实际工作原理的能力。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>打开终端或命令提示符。</p><p>类型<code>gcc --version</code>或者<code>clang --version</code>确认安装。</p><p>创建一个简单的文件，名为<code>test.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(void) { return 0; }</span></span></code></pre></div><p>编译它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc test.c -o test</span></span></code></pre></div><p>运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./test</span></span></code></pre></div><p>如果它运行时没有输出，那就完美了，你的编译器已经准备好了。您刚刚从源代码构建了第一个可执行程序。</p>`,31)])])}const u=e(i,[["render",c]]);export{h as __pageData,u as default};
